export class IntervalOverlapIndex {
  private readonly byStart: TextRange[];
  private readonly prefixMaxEnd: number[];

  constructor(ranges: TextRange[]) {
    const count = ranges.length;
    const sorted: TextRange[] = [];
    for (let i = 0; i < count; i += 1) {
      sorted.push(ranges[i]!);
    }
    let rIdx = 1;
    while (rIdx < sorted.length) {
      const curr = sorted[rIdx]!;
      let j = rIdx - 1;
      while (j >= 0 && sorted[j]!.start > curr.start) {
        sorted[j + 1] = sorted[j]!;
        j--;
      }
      sorted[j + 1] = curr;
      rIdx++;
    }
    this.byStart = sorted;
    this.prefixMaxEnd = new Array<number>();
    let running = -2147483648;
    for (let i2 = 0, count2 = sorted.length; i2 < count2; i2 += 1) {
      if (sorted[i2]!.end > running) {
        running = sorted[i2]!.end;
      }
      this.prefixMaxEnd.push(running);
    }
  }

  public overlaps(start: number, endExclusive: number): boolean {
    if (this.byStart.length === 0) {
      return false;
    }
    let low = 0;
    let high = this.byStart.length;
    while (low < high) {
      const mid = low + high >>> 1;
      if (this.byStart[mid]!.start < endExclusive) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    return low > 0 && this.prefixMaxEnd[low - 1]! > start;
  }
}

